<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Assistance · Thiebapower</title><link rel="stylesheet" href="/style.css"></head><body class="admin-body"><?php $adminPageTitle='Assistance clients';require __DIR__.'/partials/admin_shell_start.php';$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$types=['release'=>'Batterie non sortie','return'=>'Retour non reconnu','payment'=>'Paiement','other'=>'Autre']; ?>
<main class="management-main"><?php if(!$requests): ?><section class="management-card"><p>Aucune demande d’assistance.</p></section><?php endif; ?><?php foreach($requests as $t): ?><section class="management-card"><h2><?= $h($types[$t['issue']]) ?> · <?= $h($t['status']==='open'?'À traiter':'Résolu') ?></h2><p><a href="/admin/rentals/detail?reference=<?= rawurlencode($t['reference']) ?>"><?= $h($t['reference']) ?></a> · <?= $h($t['customer_name']) ?> · <?= $h($t['customer_phone']) ?></p><p><?= nl2br($h($t['message'])) ?></p><p>Reçu le <?= $h($t['created_at']) ?> UTC</p><?php if($t['status']==='resolved'): ?><p>Résolution : <?= nl2br($h($t['resolution'])) ?></p><?php elseif(App\Services\Auth::can('rentals.manage')): ?><form method="post" action="/admin/support/resolve"><input type="hidden" name="csrf" value="<?= $h($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label>Réponse et action effectuée<textarea name="resolution" required minlength="5" maxlength="2000"></textarea></label><button class="admin-button">Clôturer la demande</button></form><?php endif; ?></section><?php endforeach; ?></main><?php require __DIR__.'/partials/admin_shell_end.php'; ?></body></html>
